/*
 * A269210  Number of n X 4 0..3 arrays with some element plus some
 *          horizontally, diagonally or antidiagonally adjacent neighbor
 *          totalling three exactly once.
 * https://oeis.org/A269210
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of n×4 arrays over {0,1,2,3} that contain exactly
 *            one horizontally, diagonally or antidiagonally adjacent pair
 *            whose values sum to 3. Values are generated by a
 *            dynamic‑programming state machine that keeps track, for each
 *            last row, of the number of arrays with 0 or 1 qualifying
 *            pairs...
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 5, u64 n <= 11, u128 n <= 24,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* ----- precomputation tables (for 4×4 rows) ----- */
static uint8_t h[256];                 /* #horizontal pairs in a row */
static uint8_t diag[256][256];         /* #pairs between two rows   */
static uint16_t t_add0[256][256];      /* transitions that add 0 pairs */
static uint16_t t_add1[256][256];      /* transitions that add 1 pair  */
static uint8_t  t_add0_cnt[256];
static uint8_t  t_add1_cnt[256];
static uint8_t  state_vals[256][4];
static bool precomp = false;

/* ----- DP tables (current & next row) ----- */
static seq_t dp0[256], dp1[256];
static seq_t dp0_next[256], dp1_next[256];

/* ----- cache of a(n) values, 1‑based, up to 10000 ----- */
#define MAX_CACHE 10000
static seq_t cache[MAX_CACHE + 1] = {0};   /* all zeros initially */
static idx_t max_cached = 0;

/* ----------------------------------------------------------------- */
/* Precompute helper tables for all 256 possible rows.               */
static void precompute(void)
{
    if (precomp)
        return;
    precomp = true;

    /* Decode each 8‑bit state into 4 base‑4 digits. */
    for (int s = 0; s < 256; ++s) {
        int t = s;
        for (int j = 3; j >= 0; --j) {
            state_vals[s][j] = t & 3;
            t >>= 2;
        }
    }

    /* Horizontal pairs within a single row. */
    for (int s = 0; s < 256; ++s) {
        uint8_t v[4] = {
            state_vals[s][0], state_vals[s][1],
            state_vals[s][2], state_vals[s][3]
        };
        uint8_t cnt = 0;
        for (int j = 0; j < 3; ++j)
            if (v[j] + v[j + 1] == 3)
                ++cnt;
        h[s] = cnt;
    }

    /* Diagonal pairs between two rows and transition tables. */
    for (int s = 0; s < 256; ++s) {
        t_add0_cnt[s] = t_add1_cnt[s] = 0;
        uint8_t sv[4] = {
            state_vals[s][0], state_vals[s][1],
            state_vals[s][2], state_vals[s][3]
        };
        for (int t = 0; t < 256; ++t) {
            uint8_t tv[4] = {
                state_vals[t][0], state_vals[t][1],
                state_vals[t][2], state_vals[t][3]
            };
            uint8_t dcnt = 0;
            for (int j = 0; j < 4; ++j) {
                if (j > 0 && sv[j - 1] + tv[j] == 3)
                    ++dcnt;
                if (j < 3 && sv[j + 1] + tv[j] == 3)
                    ++dcnt;
            }
            diag[s][t] = dcnt;
            uint8_t add = h[t] + dcnt;
            if (add == 0) {
                t_add0[s][t_add0_cnt[s]++] = t;
            } else if (add == 1) {
                t_add1[s][t_add1_cnt[s]++] = t;
            }
        }
    }
}

/* ----------------------------------------------------------------- */
/* Function that returns a(n) for n >= 1.                              */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;            /* value never used for offset 1 */

    precompute();

    /* Cap n to maximum cache size.  (The problem statement guarantees n <= 10000.) */
    if (n > MAX_CACHE)
        return (seq_t)0;            /* out of range – caller will not ask for this */

    /* If the requested value is already cached, return it. */
    if (max_cached >= n)
        return cache[n];

    /* -----------------------------------------------------------------
       Initialise DP for n = 1 if this is the first call.
       Count all rows with exactly one qualifying pair.
     ----------------------------------------------------------------- */
    if (max_cached == 0) {
        for (int s = 0; s < 256; ++s) {
            dp0[s] = dp1[s] = 0;
            if (h[s] == 0)
                dp0[s] = 1;          /* row itself has 0 pairs */
            else if (h[s] == 1)
                dp1[s] = 1;          /* row itself has 1 pair */
        }
        seq_t total = 0;
        for (int s = 0; s < 256; ++s)
            total += dp1[s];
        cache[1] = total;
        max_cached = 1;
    }

    /* -----------------------------------------------------------------
       Compute subsequent rows iteratively until we reach n.
     ----------------------------------------------------------------- */
    while (max_cached < n) {
        /* clear next‑row DP tables */
        for (int j = 0; j < 256; ++j) {
            dp0_next[j] = 0;
            dp1_next[j] = 0;
        }

        /* transition from each possible current state */
        for (int s = 0; s < 256; ++s) {
            seq_t cur0 = dp0[s];
            seq_t cur1 = dp1[s];
            if (!cur0 && !cur1)
                continue;

            /* transitions that add zero pairs */
            for (uint8_t k = 0; k < t_add0_cnt[s]; ++k) {
                int t = t_add0[s][k];
                dp0_next[t] += cur0;
                dp1_next[t] += cur1;
            }

            /* transitions that add one pair – only from state with zero pairs so far */
            if (cur0) {
                for (uint8_t k = 0; k < t_add1_cnt[s]; ++k) {
                    int t = t_add1[s][k];
                    dp1_next[t] += cur0;
                }
            }
        }

        /* copy next into current */
        for (int j = 0; j < 256; ++j) {
            dp0[j] = dp0_next[j];
            dp1[j] = dp1_next[j];
        }

        /* compute the value for the new row count */
        seq_t total = 0;
        for (int j = 0; j < 256; ++j)
            total += dp1[j];
        ++max_cached;
        cache[max_cached] = total;
    }

    return cache[n];
}
